import{_ as a}from"./chunks/console-rm-release-detail.Ca3r1fnn.js";import{_ as t,o as s,c as i,a3 as o}from"./chunks/framework.DhF4LrUq.js";const k=JSON.parse('{"title":"Work with quality gates","description":"Work with quality gates - read the live gate block, submit results from CI, and override a blocking gate with an audited reason.","frontmatter":{"description":"Work with quality gates - read the live gate block, submit results from CI, and override a blocking gate with an audited reason."},"headers":[],"relativePath":"how-to/console/quality-gates.md","filePath":"how-to/console/quality-gates.md"}'),r={name:"how-to/console/quality-gates.md"};function l(n,e,h,d,c,g){return s(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="work-with-quality-gates" tabindex="-1">Work with quality gates <a class="header-anchor" href="#work-with-quality-gates" aria-label="Permalink to &quot;Work with quality gates&quot;">​</a></h1><p>Quality gates are the measurable half of release governance: a ring expects certain gates — unit tests passed, coverage above a threshold, crash-free rate, open critical bugs — and a failed or data-less required gate blocks the release&#39;s READY crossing until it passes or someone <a href="#override-a-blocking-gate">overrides</a> it with a reason. You read gates on the release dashboard; results arrive from CI.</p><p><img src="'+a+`" alt="Quality gates on the release dashboard"></p><p>The gate model — required versus advisory, fail-closed, metric-backed gates — is covered in <a href="/shipperdog/snapshot/concepts/approvals-gates">approvals and gates</a>.</p><h2 id="read-the-gate-block" tabindex="-1">Read the gate block <a class="header-anchor" href="#read-the-gate-block" aria-label="Permalink to &quot;Read the gate block&quot;">​</a></h2><p>Open a release (Releases — View). The <strong>Quality gates</strong> block lists every gate the release&#39;s ring expects, each with:</p><ul><li>its <strong>state chip</strong> — <code>passed</code>, <code>failed</code>, <code>no data yet (fail-closed)</code>, or <code>not reported yet</code>; a required failed gate also wears <code>BLOCKED</code>,</li><li>the <strong>observed value against the threshold</strong> for numeric gates (coverage <code>87.5</code> against <code>threshold 80</code>),</li><li>an <strong>evidence</strong> link — the report a human can follow,</li><li><code>from analytics</code> on metric-backed gates (their values resolve from analytics at evaluation time, not from submissions),</li><li>the override record when one exists.</li></ul><h2 id="which-gates-a-release-expects" tabindex="-1">Which gates a release expects <a class="header-anchor" href="#which-gates-a-release-expects" aria-label="Permalink to &quot;Which gates a release expects&quot;">​</a></h2><p>The ring decides. The <strong>Release rings</strong> screen shows each ring&#39;s required-gate count on its card (see <a href="/shipperdog/snapshot/how-to/console/rings-and-promotion">rings and promotion</a>); a release lists the gates of the ring it sits on. A release on a ring with no required gates states that plainly: no gates required, none reported.</p><h2 id="submit-a-result-from-ci" tabindex="-1">Submit a result from CI <a class="header-anchor" href="#submit-a-result-from-ci" aria-label="Permalink to &quot;Submit a result from CI&quot;">​</a></h2><p>Gates report through the API or the <a href="/shipperdog/snapshot/how-to/automation/cli-reference">CLI</a> — the natural home is your pipeline:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shipperdog</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> result</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> R-1028</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> coverage-threshold</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pass</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --value</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 87.5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --evidence-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://ci.example.com/run/8841/coverage</span></span></code></pre></div><ul><li><code>--status</code> is <code>pass</code> or <code>fail</code>; <code>--evidence-url</code> is mandatory — a gate without proof does not exist.</li><li>Threshold gates (like <code>coverage-threshold</code>) also take <code>--value</code>, the observed number.</li><li>Metric-backed gates (<code>crash-free-threshold</code>, <code>open-critical-bugs</code>) refuse manual submission: their values resolve from analytics, fail-closed until the feeds land.</li><li>Re-running a gate is latest-wins; the history is kept and the row shows how many results were recorded.</li></ul><p>Read the block back with <code>shipperdog gate list R-1028</code>.</p><h2 id="override-a-blocking-gate" tabindex="-1">Override a blocking gate <a class="header-anchor" href="#override-a-blocking-gate" aria-label="Permalink to &quot;Override a blocking gate&quot;">​</a></h2><p>The governed exception — exactly once, with a record:</p><ol><li>On a gate that is not passed (failed, or no data yet), click <strong>Override</strong>.</li><li>Write the <strong>reason</strong> — the dialog marks it <em>mandatory, audited</em>.</li><li>Confirm with <strong>Override</strong>.</li></ol><p>The gate keeps its recorded state; only the override stops it blocking. The row permanently shows who overrode, why, and when, and the dashboard surfaces the override. Overriding requires the gate-override authority (release managers and organization admins).</p><div class="tip custom-block"><p class="custom-block-title">The feedback shortcut</p><p>The <code>open-critical-bugs</code> gate reads the release&#39;s feedback block live — <a href="/shipperdog/snapshot/how-to/console/feedback-triage">triage a report</a> and the next promotion attempt re-evaluates. Resolve the bug instead of overriding the gate whenever you can.</p></div><p><strong>Related guides:</strong> <a href="/shipperdog/snapshot/how-to/console/rings-and-promotion">rings and promotion</a> · <a href="/shipperdog/snapshot/how-to/console/feedback-triage">triage feedback</a> · <a href="/shipperdog/snapshot/how-to/automation/cli-reference">CLI reference</a></p>`,20)])])}const m=t(r,[["render",l]]);export{k as __pageData,m as default};
